    roofSystem: "",
    scopeItems: [],
    quantities: [],
    unitPrices: [],
    alternates: [],
    exclusions: [],
    allowances: [],
    taxes: [],
    totalPrice: 0,
    salesperson: "",
    internalJobNotes: "",
    warranty: "",
    paymentSchedule: "",
    estimatedSchedule: "",
